import b200probe, torch, statistics as st, sys, time
def gen(W, THREADS, X, T, S_, NOTAB=0, COPY=0):
    LANES = 64 // W
    regs = lambda n, p: ",".join(f"%{p+i}" for i in range(n))
    def ldasm(mode):
        return {0: "ld.global.nc.L1::no_allocate", 1: "ld.global", 2: "ld.global.nc"}[mode]
    def LD(name, mode):
        outs = ",".join(f'"=f"(v[{i}])' for i in range(W))
        rl = ",".join(f"%{i}" for i in range(W))
        return f'__device__ __forceinline__ void {name}(const float* p, float* v) {{ asm volatile("{ldasm(mode)}.v{W}.f32 {{{rl}}}, [%{W}];" : {outs} : "l"(p)); }}\n'
    ins = ",".join(f'"f"(v[{i}])' for i in range(W))
    rl = ",".join(f"%{i+1}" for i in range(W))
    if S_ == 0:
        stf = f'__device__ __forceinline__ void STV(float* p, const float* v, unsigned long long pol) {{ asm volatile("st.global.L2::cache_hint.v{W}.f32 [%0], {{{rl}}}, %{W+1};" :: "l"(p), {ins}, "l"(pol) : "memory"); }}\n'
    else:
        stf = f'__device__ __forceinline__ void STV(float* p, const float* v, unsigned long long pol) {{ asm volatile("st.global.v{W}.f32 [%0], {{{rl}}};" :: "l"(p), {ins} : "memory"); }}\n'
    src = LD("LDX", X) + LD("LDT", T) + stf
    ROWS = THREADS // LANES
    body_tab = "" if NOTAB else f"""
    const float* cp = cs + (size_t)s * 128 + j * {W};
    const float* sp = sn + (size_t)s * 128 + j * {W};
    LDT(cp, cl); LDT(cp + 64, ch); LDT(sp, sl); LDT(sp + 64, sh);"""
    if NOTAB:
        body_tab = f"""
    for (int e = 0; e < {W}; ++e) {{ cl[e] = 0.5f + e; ch[e] = 0.25f + e; sl[e] = 0.125f * e; sh[e] = 0.75f; }}"""
    calc = ("for (int e = 0; e < %d; ++e) { ol[e] = xl[e]; oh[e] = xh[e]; }" % W) if COPY else (
        "for (int e = 0; e < %d; ++e) { ol[e] = xl[e] * cl[e] - xh[e] * sl[e]; oh[e] = xh[e] * ch[e] + xl[e] * sh[e]; }" % W)
    src += f"""
extern "C" __global__ void __launch_bounds__({THREADS}) rope(const float* __restrict__ q, const float* __restrict__ k,
 const float* __restrict__ cs, const float* __restrict__ sn, float* __restrict__ qo, float* __restrict__ ko,
 unsigned Rq, unsigned R, unsigned S) {{
    const unsigned j = threadIdx.x % {LANES};
    const unsigned r = blockIdx.x * {ROWS} + threadIdx.x / {LANES};
    if (r >= R) return;
    const float* x; float* y; unsigned rl;
    if (r < Rq) {{ x = q; y = qo; rl = r; }} else {{ x = k; y = ko; rl = r - Rq; }}
    const unsigned s = rl % S;
    const float* xp = x + (size_t)rl * 128 + j * {W};
    y += (size_t)rl * 128 + j * {W};
    float xl[{W}], xh[{W}], cl[{W}], ch[{W}], sl[{W}], sh[{W}], ol[{W}], oh[{W}];
    LDX(xp, xl); LDX(xp + 64, xh);
    {body_tab}
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
    #pragma unroll
    {calc}
    STV(y, ol, pol); STV(y + 64, oh, pol);
}}
"""
    return src, ROWS

VARS = {
 "r0":   dict(W=8, THREADS=64, X=0, T=2, S_=0),
 "a_xplain": dict(W=8, THREADS=64, X=1, T=2, S_=0),
 "b_tplain": dict(W=8, THREADS=64, X=0, T=1, S_=0),
 "c_v4_128": dict(W=4, THREADS=128, X=1, T=1, S_=1),
 "d_stplain": dict(W=8, THREADS=64, X=0, T=2, S_=1),
 "e1_32t4r": dict(W=8, THREADS=32, X=0, T=2, S_=0),
 "e2_32t2r_v4": dict(W=4, THREADS=32, X=1, T=1, S_=1),
 "f1_notab": dict(W=8, THREADS=64, X=0, T=2, S_=0, NOTAB=1),
 "f2_copy": dict(W=8, THREADS=64, X=0, T=2, S_=0, NOTAB=1, COPY=1),
}
SIZES = [(1,8,8,128),(1,40,8,131),(2,32,4,211),(4,24,6,293)]
import json
res = {}
kern = {}
for n, v in VARS.items():
    src, rows = gen(**v)
    try:
        kern[n] = (b200probe.cuda_kernel(src, "rope"), rows, v["THREADS"])
    except Exception as e:
        print("compile fail", n, str(e)[:500]); 
print("compiled", list(kern))
def mk(B,H,Hk,S):
    q = torch.randn(B,H,S,128,device="cuda"); k = torch.randn(B,Hk,S,128,device="cuda")
    c = torch.rand(S,128,device="cuda")*2-1; s_ = torch.rand(S,128,device="cuda")*2-1
    return q,k,c,s_,torch.empty_like(q),torch.empty_like(k)
t0=time.time()
for sz in SIZES[:2]:
    B,H,Hk,S = sz
    t = mk(*sz); Rq=B*H*S; R=Rq+B*Hk*S
    ref_o = None
    for rep in range(5):
        for n,(k_,rows,thr) in kern.items():
            grid = ((R+rows-1)//rows,)
            fn = lambda q,k,c,s,qo,ko: k_(grid,(thr,),q,k,c,s,qo,ko,Rq,R,S)
            us = b200probe.harness_time(fn, t[:4], t[4:])
            res.setdefault((sz,n),[]).append(us)
    # correctness vs r0 for one variant set
    print(sz, "elapsed", round(time.time()-t0))
    for n in kern:
        v = res[(sz,n)]; print(f"  {n:14s} med {st.median(v):.3f} min {min(v):.3f} max {max(v):.3f}")

